// Deterministic Style Preset Resolution and Master Prompt Preparation (formerly WF-04)
const job = $('Execute Workflow Trigger').first().json;
const presets = $input.all().map(i => i.json).filter(p => p && p.preset_id);

const presetMap = {};
for (const p of presets) {
  presetMap[String(p.preset_id).toUpperCase().trim()] = p;
}

const focus = String(job.content_focus || '').toLowerCase();
const format = String(job.content_format || '').toLowerCase();
const template = String(job.prompt_template || '').trim();
const templateUpper = template.toUpperCase();

// 1. Direct match check: allow adding new presets without rebuilding workflow
let selectedPresetId = '';
if (job.style_preset_id && presetMap[String(job.style_preset_id).toUpperCase()]) {
  selectedPresetId = String(job.style_preset_id).toUpperCase();
} else if (presetMap[templateUpper]) {
  selectedPresetId = templateUpper;
} else if (focus.includes('deal') || focus.includes('discount') || template.toLowerCase().includes('deal')) {
  selectedPresetId = 'DEAL_V1';
} else if (focus.includes('event') || focus.includes('happening') || template.toLowerCase().includes('event')) {
  selectedPresetId = 'EVENT_V1';
} else if (focus.includes('gift') || focus.includes('voucher') || template.toLowerCase().includes('gift')) {
  selectedPresetId = 'EGIFT_V1';
} else if (focus.includes('birthday') || focus.includes('celebration') || template.toLowerCase().includes('birthday')) {
  selectedPresetId = 'BIRTHDAY_V1';
} else if (format === 'story') {
  selectedPresetId = 'STORY_V1';
} else if (format === 'carousel') {
  selectedPresetId = 'CAROUSEL_V1';
} else {
  selectedPresetId = 'BUSINESS_V1';
}

// 2. Fetch resolved preset configuration
const resolvedPreset = presetMap[selectedPresetId] || {
  preset_id: selectedPresetId,
  headline_color: '#FFFFFF',
  body_color: '#E0E0E0',
  overlay_color: '#0D0F12',
  overlay_opacity: 0.65,
  accent_color: '#D4AF37',
  cta_bg_color: '#D4AF37',
  cta_text_color: '#0D0F12',
  logo_treatment: 'TOP_RIGHT_CLEAN',
  lower_third_treatment: 'MINIMAL_DARK',
  border_treatment: 'NONE',
  typography_rules: 'Inter, Semi-Bold 600, Minimal Text'
};

const promptId = `PROMPT_${templateUpper.replace(/[^A-Z0-9]/g, '_') || 'GENERAL'}`;
const promptVersion = 'v3.5';

return [{
  json: {
    ...job,
    style_preset_id: selectedPresetId,
    style_preset: resolvedPreset,
    prompt_id: promptId,
    prompt_version: promptVersion,
    prompt_template_name: template,
    preset_resolved_at: new Date().toISOString()
  }
}];

const job = $('Resolve Preset & Style Tokens').first().json;
const historyRows = $('Get Recent Creative History').all().map(i => i.json).filter(h => h && (h.hook || h.concept));

// Take up to 10 most recent records containing full semantic context
const recentSlice = historyRows.slice(-10).map(h => ({
  hook: h.hook || '',
  concept: h.concept || '',
  angle: h.creative_direction || '',
  promoted_listing: h.promoted_listing_id || '',
  content_format: h.content_format || '',
  selected_assets: h.selected_assets || [],
  created_at: h.created_at || ''
}));

const systemPrompt = `You are TUDDEH's chief creative strategist and executive copywriter.\n` +
`Generate an experience-first, authentic, high-converting social media package in strict JSON.\n` +
`TUDDEH Brand Rules:\n` +
`- Experience-first, sensory storytelling. Never sound like cheap marketing hype.\n` +
`- On-screen text overlays must be short, punchy, and minimal (max 1-3 lines).\n` +
`- SEMANTIC DUPLICATION PREVENTION: Materially vary the hook, angle, and narrative concept from the recent history provided.\n` +
`- Strictly output valid JSON matching the requested schema.`;

const userPayload = {
  business_name: job.business_name,
  category: job.category || 'Hospitality/Lifestyle',
  content_focus: job.content_focus,
  content_format: job.content_format,
  selected_listing: job.resolved_listing || null,
  creative_direction_guidance: job.creative_direction || '',
  style_preset_id: job.style_preset_id,
  style_preset_tokens: job.style_preset,
  candidate_assets: (job.selected_candidate_assets || []).map(a => ({ id: a.id, name: a.name })),
  recent_creative_history_to_avoid: recentSlice,
  revision_notes: job.revision_notes || '',
  required_schema: {
    headline: 'Short, magnetic hook / headline',
    experience_line: 'One evocative sentence capturing the physical atmosphere and experience',
    caption: 'Compelling 2-3 paragraph caption written for human connection',
    hashtags: ['3-5 specific niche and local tags, no generic tag spam'],
    CTA: 'Direct and natural call to action',
    on_screen_text: ['Line 1', 'Line 2 (optional)'],
    selected_assets: ['Chosen asset IDs from candidate_assets'],
    creative_direction: 'Concise summary of the visual concept and hook angle',
    recommended_publish_date: 'YYYY-MM-DD (optimal date in next 2-5 days)',
    recommended_publish_time: 'HH:MM (e.g. 11:30, 18:45)'
  }
};

return [{
  json: {
    ...job,
    ai_system_prompt: systemPrompt,
    ai_user_payload: JSON.stringify(userPayload),
    recent_history: recentSlice
  }
}];

const rawContent = $json.choices?.[0]?.message?.content;
if (!rawContent) throw new Error('OpenAI returned empty response.');

let parsed;
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  throw new Error(`Failed to parse OpenAI JSON response: ${e.message}`);
}

const prep = $('Build Creative Request Payload').first().json;
const history = prep.recent_history || [];

const newHook = String(parsed.headline || parsed.experience_line || '').trim().toLowerCase();
const newConcept = String(parsed.creative_direction || '').trim().toLowerCase();

// Verify that the output does not closely mirror recent history
const isDuplicate = history.some(h => {
  const prevHook = String(h.hook || '').trim().toLowerCase();
  const prevConcept = String(h.concept || h.angle || '').trim().toLowerCase();
  return (newHook && prevHook && (newHook.includes(prevHook) || prevHook.includes(newHook))) ||
         (newConcept && prevConcept && (newConcept.includes(prevConcept) || prevConcept.includes(newConcept)));
});

return [{
  json: {
    ...prep,
    ai_package: parsed,
    semantic_duplicate_detected: isDuplicate,
    recommended_publish_date: parsed.recommended_publish_date || new Date().toISOString().split('T')[0],
    recommended_publish_time: parsed.recommended_publish_time || '12:00'
  }
}];

// Direct Video Asset Selection (formerly WF-07)
const job = $json;
const aiPkg = job.ai_package || {};
const candidateAssets = job.approved_assets || job.selected_candidate_assets || [];

// Resolve source video ID from AI selection or candidate assets
let heroAsset = (candidateAssets.find(a => a.id === (aiPkg.selected_assets && aiPkg.selected_assets[0]))) || candidateAssets[0];

if (!heroAsset || !heroAsset.id) {
  throw new Error('WF-05 Reel Generation: No source video asset found in candidate media.');
}

const safeJobId = String(job.internal_job_id || 'JOB').replace(/[^a-zA-Z0-9_]/g, '');
const filename = `${safeJobId}_${heroAsset.name || 'VIDEO.mp4'}`;

return [{
  json: {
    ...job,
    hero_asset: heroAsset,
    rendered_filename: filename,
    rendered_type: 'VIDEO',
    media_format: 'mp4',
    source_video_id: heroAsset.id,
    source_video_name: heroAsset.name,
    source_video_url: `https://drive.google.com/file/d/${heroAsset.id}/view`,
    render_verified: true,
    video_editing_status: 'DIRECT_PASSTHROUGH',
    rendered_at: new Date().toISOString()
  }
}];

// Prepare prompt for OpenAI Image API (DALL-E 3) incorporating style preset (formerly WF-06)
const job = $json;
const preset = job.style_preset || {};
const pkg = job.ai_package || {};
const presetId = String(job.style_preset_id || 'BUSINESS_V1').toUpperCase();

let thematicGuidance = '';
if (presetId.includes('DEAL')) {
  thematicGuidance = 'Highlighting a hero offering or signature dining/retail feature, crisp focus, minimalist premium setting, inviting atmosphere with clear negative space.';
} else if (presetId.includes('EVENT')) {
  thematicGuidance = 'Atmospheric ambient lighting, subtle depth of field, warm social celebration, capturing authentic energy and venue texture.';
} else if (presetId.includes('EGIFT')) {
  thematicGuidance = 'Sophisticated editorial lifestyle presentation, giftable luxury aesthetic, elegant and restrained composition.';
} else if (presetId.includes('BIRTHDAY')) {
  thematicGuidance = 'Subtle celebratory bokeh, warm golden hour tones, celebratory and joyful yet refined hospitality vibe.';
} else {
  thematicGuidance = 'Architectural, environmental interior and exterior authenticity, timeless craft and hospitality presentation.';
}

const accentTone = preset.accent_color || '#D4AF37';
const concept = pkg.creative_direction || pkg.experience_line || `Experience ${job.business_name}`;

const imagePrompt = `High-end commercial editorial photography for ${job.business_name}. ` +
  `Visual Concept: ${concept}. ` +
  `Art Direction: ${thematicGuidance} ` +
  `Color Palette: Subtle natural warmth with harmonic accents around ${accentTone}. ` +
  `Execution rules: Shot on professional 35mm lens, f/2.4, natural diffused lighting. ` +
  `CRITICAL BRAND RULE: Absolutely NO text overlays, NO graphic banners, NO artificial icons, NO watermark, photorealistic commercial look.`;

const rev = Number(job.approval_version || job.current_revision || 1);
const safeBiz = String(job.business_name || 'BIZ').replace(/[^a-zA-Z0-9]/g, '_');
const filename = `STATIC_${safeBiz}_${job.internal_job_id}_REV${rev}.png`;

return [{
  json: {
    ...job,
    image_api_prompt: imagePrompt,
    target_filename: filename,
    current_revision: rev
  }
}];

const response = $json;
const b64 = response.data?.[0]?.b64_json;
const job = $('Prepare Static Image Prompt').first().json;

if (!b64) {
  throw new Error('OpenAI Image API did not return base64 image data.');
}

const filename = job.target_filename;

return [{
  json: {
    ...job,
    rendered_filename: filename,
    rendered_type: 'STATIC_IMAGE',
    media_format: 'png',
    generated_at: new Date().toISOString()
  },
  binary: {
    data: {
      data: b64,
      mimeType: 'image/png',
      fileName: filename
    }
  }
}];

// Story and Carousel Builder (formerly WF-08)
const job = $json;
const format = String(job.content_format || '').toLowerCase();
const preset = job.style_preset || {};
const pkg = job.ai_package || {};

const isStory = format === 'story';
const targetAspect = isStory ? '9:16' : '4:5';

const textPoints = (pkg.on_screen_text && pkg.on_screen_text.length > 0)
  ? pkg.on_screen_text
  : [pkg.headline, pkg.experience_line, pkg.CTA].filter(Boolean);

let slideCount = 1;
if (isStory) {
  slideCount = Math.min(3, Math.max(1, textPoints.length));
} else {
  slideCount = Math.min(7, Math.max(3, textPoints.length));
}

const slides = [];
for (let i = 0; i < slideCount; i++) {
  let slideHeadline = '';
  let slideBody = '';

  if (i === 0) {
    slideHeadline = pkg.headline || job.marketing_job;
    slideBody = pkg.experience_line || textPoints[0] || '';
  } else if (i === slideCount - 1) {
    slideHeadline = textPoints[i] || 'Next Step';
    slideBody = pkg.CTA || 'Visit us today';
  } else {
    slideHeadline = `Highlight ${i}`;
    slideBody = textPoints[i] || '';
  }

  slides.push({
    slide_number: i + 1,
    total_slides: slideCount,
    aspect_ratio: targetAspect,
    headline: slideHeadline,
    body_text: slideBody,
    bg_color: preset.overlay_color || '#0D0F12',
    accent_color: preset.accent_color || '#D4AF37',
    text_color: preset.headline_color || '#FFFFFF',
    pagination_indicator: `${i + 1}/${slideCount}`
  });
}

const width = isStory ? 1080 : 1080;
const height = isStory ? 1920 : 1350;
const heroSlide = slides[0];

const svgCover = `
<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
  <rect width="100%" height="100%" fill="${heroSlide.bg_color}"/>
  <rect x="80" y="80" width="${width - 160}" height="${height - 160}" rx="24" fill="none" stroke="${heroSlide.accent_color}" stroke-width="4" opacity="0.4"/>
  <text x="${width / 2}" y="${height * 0.35}" font-family="Arial, sans-serif" font-size="36" font-weight="bold" fill="${heroSlide.accent_color}" text-anchor="middle" letter-spacing="4">${(job.business_name || '').toUpperCase()}</text>
  <text x="${width / 2}" y="${height * 0.45}" font-family="Arial, sans-serif" font-size="64" font-weight="bold" fill="${heroSlide.text_color}" text-anchor="middle">${heroSlide.headline.slice(0, 30)}</text>
  <text x="${width / 2}" y="${height * 0.55}" font-family="Arial, sans-serif" font-size="32" fill="#CCCCCC" text-anchor="middle">${heroSlide.body_text.slice(0, 60)}</text>
  <text x="${width / 2}" y="${height * 0.85}" font-family="Arial, sans-serif" font-size="28" fill="${heroSlide.accent_color}" text-anchor="middle">${heroSlide.pagination_indicator}</text>
</svg>`;

const safeBiz = String(job.business_name || 'BIZ').replace(/[^a-zA-Z0-9]/g, '_');
const filename = `${safeBiz}_${isStory ? 'STORY' : 'CAROUSEL'}_COVER.svg`;

return [{
  json: {
    ...job,
    rendered_type: isStory ? 'STORY' : 'CAROUSEL',
    media_format: 'svg',
    slide_count: slideCount,
    slides: slides,
    rendered_filename: filename
  },
  binary: {
    data: {
      data: Buffer.from(svgCover).toString('base64'),
      mimeType: 'image/svg+xml',
      fileName: filename
    }
  }
}];
